/**
 * Remotion entry — Executive Command Bridge film (FINN narration).
 *
 * This is BUILD TOOLING, not application code. It lives outside src/ and is
 * excluded from the app tsconfig/eslint; Remotion is pulled ephemerally by
 * `npx remotion render` and is never added to the app bundle or deps.
 *
 * It composites the seven bridge scenes (title cards) with the Layan
 * narration MP3s generated by scripts/generate-finn-audio.mjs into one
 * board-room film — the complete fallback when HeyGen is not configured.
 *
 * Render (from remotion/, resolving assets from the app's public/ dir):
 *   cd remotion && bun install
 *   ELEVENLABS_LANG=ar bunx remotion render index.tsx BridgeFilm \
 *     ../public/media/bridge/bridge-final.mp4 --public-dir=../public --codec=h264
 */
import React from "react";
import {
  Audio,
  AbsoluteFill,
  Composition,
  Sequence,
  interpolate,
  registerRoot,
  staticFile,
  useCurrentFrame,
} from "remotion";

const FPS = 30;

/** Scene id + on-screen title/kicker, mirroring executive-bridge-content.ts.
 *  Durations are estimates; the narration audio is the timing authority. */
const SCENES = [
  {
    id: "command-pulse",
    n: 1,
    kicker: "لحظة القيادة",
    title: "كل ما يهم القيادة. في لحظة واحدة.",
    accent: "#1E8BFF",
    seconds: 26,
  },
  {
    id: "decision-engine",
    n: 2,
    kicker: "محرك القرار",
    title: "من الإشارة إلى القرار الموثّق.",
    accent: "#2DE38C",
    seconds: 28,
  },
  {
    id: "regional-grid",
    n: 3,
    kicker: "الشبكة الإقليمية",
    title: "أربع مناطق. قيادة واحدة.",
    accent: "#16D9FF",
    seconds: 27,
  },
  {
    id: "aria-council",
    n: 4,
    kicker: "مجلس FINN",
    title: "ذكاء تنفيذي يعمل مع القيادة، لا بدلاً عنها.",
    accent: "#A855F7",
    seconds: 28,
  },
  {
    id: "digital-twin",
    n: 5,
    kicker: "التوأم التشغيلي",
    title: "الميدان يصبح مفهوماً قبل أن يصبح أزمة.",
    accent: "#2DE38C",
    seconds: 27,
  },
  {
    id: "sovereign-trust",
    n: 6,
    kicker: "الثقة السيادية",
    title: "كل قرار محمي. كل إجراء قابل للتفسير.",
    accent: "#F5A524",
    seconds: 27,
  },
  {
    id: "activation",
    n: 7,
    kicker: "القرار التالي",
    title: "من الرؤية إلى قيمة قابلة للقياس خلال تسعين يوماً.",
    accent: "#F5A524",
    seconds: 28,
  },
] as const;

const LANG = process.env.ELEVENLABS_LANG === "en" ? "en" : "ar";

function SceneCard({ scene }: { scene: (typeof SCENES)[number] }) {
  const frame = useCurrentFrame();
  const appear = interpolate(frame, [0, 18], [0, 1], { extrapolateRight: "clamp" });
  const rise = interpolate(frame, [0, 24], [24, 0], { extrapolateRight: "clamp" });
  return (
    <AbsoluteFill
      style={{
        background: "radial-gradient(circle at 50% 12%, rgba(19,80,130,0.35), #020711 60%)",
        fontFamily: "Tajawal, 'IBM Plex Sans Arabic', system-ui, sans-serif",
        direction: "rtl",
        alignItems: "center",
        justifyContent: "center",
        padding: 120,
      }}
    >
      <div
        style={{
          opacity: appear,
          transform: `translateY(${rise}px)`,
          textAlign: "center",
          maxWidth: 1400,
        }}
      >
        <div
          style={{
            display: "inline-block",
            color: scene.accent,
            border: `1px solid ${scene.accent}66`,
            borderRadius: 999,
            padding: "10px 26px",
            fontSize: 30,
            letterSpacing: 6,
            marginBottom: 40,
          }}
        >
          {`0${scene.n}`} · {scene.kicker}
        </div>
        <h1
          style={{ color: "#F4FAFF", fontSize: 78, lineHeight: 1.25, fontWeight: 800, margin: 0 }}
        >
          {scene.title}
        </h1>
        <div style={{ marginTop: 56, color: "#8EA6BE", fontSize: 30, letterSpacing: 4 }}>
          NEXIOS · جسر القيادة التنفيذي · صوت FINN
        </div>
      </div>
    </AbsoluteFill>
  );
}

function BridgeFilm() {
  let cursor = 0;
  return (
    <AbsoluteFill style={{ backgroundColor: "#020711" }}>
      {SCENES.map((scene) => {
        const from = cursor;
        const durationInFrames = Math.round(scene.seconds * FPS);
        cursor += durationInFrames;
        const audioFile = `media/bridge/audio/${String(scene.n).padStart(2, "0")}-${scene.id}.${LANG}.mp3`;
        return (
          <Sequence key={scene.id} from={from} durationInFrames={durationInFrames}>
            <SceneCard scene={scene} />
            <Audio src={staticFile(audioFile)} />
          </Sequence>
        );
      })}
    </AbsoluteFill>
  );
}

const TOTAL_FRAMES = SCENES.reduce((sum, s) => sum + Math.round(s.seconds * FPS), 0);

export function RemotionRoot() {
  return (
    <Composition
      id="BridgeFilm"
      component={BridgeFilm}
      durationInFrames={TOTAL_FRAMES}
      fps={FPS}
      width={1920}
      height={1080}
    />
  );
}

registerRoot(RemotionRoot);
